@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.2484 0 0);

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.1371 0.036 258.53);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.1371 0.036 258.53);

  --primary: oklch(0.658 0.2308 16.91);
  --primary-foreground: oklch(1 0 0);

  --secondary: oklch(0.2484 0 0);
  --secondary-foreground: oklch(1 0 0);

  --muted: oklch(0.9772 0 0);
  --muted-foreground: oklch(0.5547 0.0407 257.44);

  --accent: oklch(0.9772 0 0);
  --accent-foreground: oklch(0.2079 0.0399 265.73);

  --destructive: oklch(0.6368 0.2078 25.33);
  --destructive-foreground: oklch(0.9838 0.0035 247.86);

  --border: oklch(0.9001 0 0);
  --input: oklch(0.929 0.0126 255.53);
  --ring: oklch(0.2484 0 0);

  --radius: 0.5rem;

  /* Shadow overrides — light theme, warm subtle shadows */
  --shadow-2xs: 0 1px 2px 0 rgba(0,0,0,0.04);
  --shadow-xs:  0 1px 2px 0 rgba(0,0,0,0.06);
  --shadow-sm:  0 1px 3px 0 rgba(0,0,0,0.08), 0 1px 2px -1px rgba(0,0,0,0.06);
  --shadow:     0 1px 3px 0 rgba(0,0,0,0.1),  0 1px 2px -1px rgba(0,0,0,0.08);
  --shadow-md:  0 4px 6px -1px rgba(0,0,0,0.08), 0 2px 4px -2px rgba(0,0,0,0.06);
  --shadow-lg:  0 8px 16px -2px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.06), 0 0 0 1px rgba(0,0,0,0.04);
  --shadow-xl:  0 16px 24px -4px rgba(0,0,0,0.12), 0 8px 10px -6px rgba(0,0,0,0.08);
}

.dark {
  --background: oklch(0.1371 0.036 258.53);
  --foreground: oklch(0.9838 0.0035 247.86);

  --card: oklch(0.1371 0.036 258.53);
  --card-foreground: oklch(0.9838 0.0035 247.86);

  --popover: oklch(0.1371 0.036 258.53);
  --popover-foreground: oklch(0.9838 0.0035 247.86);

  --primary: oklch(0.9838 0.0035 247.86);
  --primary-foreground: oklch(0.2079 0.0399 265.73);

  --secondary: oklch(0.28 0.0369 259.97);
  --secondary-foreground: oklch(0.9838 0.0035 247.86);

  --muted: oklch(0.28 0.0369 259.97);
  --muted-foreground: oklch(0.7107 0.0351 256.79);

  --accent: oklch(0.28 0.0369 259.97);
  --accent-foreground: oklch(0.9838 0.0035 247.86);

  --destructive: oklch(0.3959 0.1331 25.72);
  --destructive-foreground: oklch(0.9838 0.0035 247.86);

  --border: oklch(0.28 0.0369 259.97);
  --input: oklch(0.28 0.0369 259.97);
  --ring: oklch(0.8688 0.0198 252.85);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: var(--font-geist-sans), ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
}
